import csv
import io
import posixpath
from datetime import date, datetime
from decimal import Decimal, ROUND_HALF_UP

def reserve(p):
    stock=dict(p['stock'])
    for k,v in p['request'].items(): stock[k]=stock.get(k,0)-v
    return {'accepted':True,'stock':stock}

def replay(p):
    seen=set(); total=0
    for e in p:
        if e['id'] not in seen: total+=e['delta']; seen.add(e['id'])
    return total

def reorder(p):
    return sorted(k for k,v in p['points'].items() if p['stock'].get(k,0)<=v)

