import csv
import io
import posixpath
from datetime import date, datetime
from decimal import Decimal, ROUND_HALF_UP

def allocate(p):
    need=p['quantity']; allocations=[]
    for batch in p['batches']:
        take=min(need,batch['count'])
        if take: allocations.append({'id':batch['id'],'count':take})
        need-=take
    return {'allocations':allocations,'unmet':need}

def available(p):
    return {k:max(v-p['reserved'].get(k,0),0) for k,v in p['on_hand'].items()}

